//! Source-bound plans over actual native inventory, not deserialized candidates.
//! Terminal-floor change is separate from executable cash. Plans do not credit
//! fills, release protected inventory, borrow advances or authorize networking.
use crate::{authority::Activation,feedback::Result,relationship_strategy::{CertifiedComponent,Policy},package_admission,daily_windows};
use moloch_replay::{session::Session,money,Side as NativeSide};
use moloch_relationship_arbitrage::{Instrument,Side,Book,Level,depth_cost,UNIT};
use serde::Serialize;
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::collections::{BTreeMap,BTreeSet};
fn need(ok:bool,code:&'static str)->Result<()>{if ok{Ok(())}else{Err(code.into())}}
fn hash<T:Serialize>(v:&T)->Result<String>{Ok(format!("{:x}",Sha256::digest(serde_json::to_vec(v)?)))}
fn add(a:i128,b:i128)->Result<i128>{a.checked_add(b).ok_or_else(||"PORTFOLIO_RANGE".into())}
fn mul(a:i128,b:u64)->Result<i128>{a.checked_mul(b as i128).ok_or_else(||"PORTFOLIO_RANGE".into())}
fn side(s:Side)->&'static str{if s==Side::Yes{"YES"}else{"NO"}}
#[derive(Clone,Copy,Serialize,PartialEq,Eq,Debug)]#[serde(rename_all="snake_case")]pub enum Mode{MarginalAcquisition,WholeUnwind}
#[derive(Clone,Serialize,Debug)]#[serde(rename_all="camelCase")]pub struct Leg{pub market_id:String,pub exchange_id:String,pub contract_id:String,pub side:String,pub action:String,pub quantity:u64,pub limit_price:String,pub book_hash:String}
/// No Deserialize/Clone/public constructor. Every plan comes from current bank
/// positions and a source-validated opaque certified payoff component.
pub struct Plan{mode:Mode,proof:Value,reserve:Value,legs:Vec<Leg>,expires:u64,head:Value,funding:i128,improvement:i128,statewise:i128,classification:String}
impl Plan{
 pub fn mode(&self)->Mode{self.mode}pub fn proof(&self)->&Value{&self.proof}pub fn reserve_event(&self)->&Value{&self.reserve}pub fn legs(&self)->&[Leg]{&self.legs}
 pub fn package_id(&self)->&str{self.reserve["packageId"].as_str().expect("constructed package ID")}pub fn expires_at_ms(&self)->u64{self.expires}pub fn gross_funding(&self)->i128{self.funding}pub fn benchmark_surplus(&self)->i128{self.improvement}pub fn minimum_statewise_delta(&self)->i128{self.statewise}pub fn classification(&self)->&str{&self.classification}
 pub fn validate_physical_rule(&self,exchange:&str,r:&baal_transport_service::Receipt)->Result<()>{let binding=&self.proof["component"]["ruleBindings"][exchange];need(r.status==200&&r.endpoint==binding["endpoint"],"PORTFOLIO_RULE_BINDING")?;let digest=match binding["kind"].as_str(){Some("exact_receipt_v1")=>hash(r)?,Some("complete_rule_body_v2")=>hash(&r.data)?,_=>return Err("PORTFOLIO_RULE_BINDING".into())};need(digest==binding["sha256"],"PORTFOLIO_RULE_CHANGED")}
 pub fn validate_bank(&self,bank:&Session,now:u64)->Result<()>{need(now<self.expires&&bank.durable_head()==self.head,"PORTFOLIO_BANK_CHANGED_OR_EXPIRED")}
}
struct Context{held:Vec<(Instrument,u64)>,holdings:Value,parents:Vec<String>,books:BTreeMap<String,Book>,hashes:BTreeMap<String,String>,floor:i128,maximum_payout:i128,liquidation_cash:Option<i128>,expires:u64}
fn context(bank:&Session,a:&Activation,c:&CertifiedComponent,p:&Policy,entry_until:u64,buy:bool)->Result<Context>{
 need(bank.engine().is_live()&&bank.live_account_seed().is_some_and(|s|s["runId"]==a.run_id)&&c.scope().tournament_id==a.tournament_id&&c.scope().tournament_slug==a.tournament_slug,"PORTFOLIO_SCOPE")?;
 need(p.now_ms>=c.validated_at_ms()&&p.now_ms<c.expires_at_ms()&&!bank.engine().package_blocks_submissions(),"PORTFOLIO_UNRESOLVED_OR_STALE")?;
 let policy=bank.engine().policy();need(policy["maximumCommitted"]==a.maximum_committed&&policy["maximumMarketCost"]==a.maximum_market_cost&&policy["quantity"].as_u64()==Some(a.maximum_quantity as u64),"PORTFOLIO_CAPS_CHANGED")?;
 need(p.entry_fee_per_share_per_leg==0&&policy["feeBps"]==0&&policy["feePerShare"]=="0.000000"&&p.buffer_per_share>=0&&p.minimum_surplus>0&&p.maximum_quantity>0&&p.quantities.len()<=32,"PORTFOLIO_FEES_OR_BUDGET")?;
 if buy{need(policy["entriesEnabled"]==true&&daily_windows::clock(policy["entryStopAt"].as_str().ok_or("PORTFOLIO_ENTRY")?)?==entry_until&&p.now_ms<entry_until,"PORTFOLIO_ENTRY")?;}
 let exchanges:BTreeSet<_>=c.compiled().contracts().iter().map(|x|x.exchange_id.as_str()).collect();let mut held=vec![];let mut holdings=vec![];
 for(i,contract)in c.compiled().contracts().iter().enumerate(){for(s,native)in [(Side::Yes,NativeSide::Yes),(Side::No,NativeSide::No)]{let q=bank.engine().wallet.quantity(&contract.exchange_id,native);if q>0{held.push((Instrument{contract:i,side:s},q));holdings.push(json!({"marketId":contract.market_id,"exchangeId":contract.exchange_id,"side":side(s),"quantity":q}));}}}
 for q in bank.engine().order_records(){if q["retired"]==false&&q["exchangeId"].as_str().is_some_and(|ex|exchanges.contains(ex)){return Err("PORTFOLIO_COMPONENT_PENDING_ORDER".into())}}
 let mut parents=vec![];for package in bank.engine().package_records().as_array().ok_or("PORTFOLIO_PACKAGES")?{if package["phase"]=="no_execution"||package.get("protectionReleased")==Some(&json!(true)){continue}let legs=package["legs"].as_array().ok_or("PORTFOLIO_PACKAGE_LEGS")?;if !legs.iter().any(|l|l["exchangeId"].as_str().is_some_and(|e|exchanges.contains(e))){continue}need(package["phase"]=="complete"&&legs.iter().all(|l|l["terminalReconciled"]==true&&l["filled"]==l["quantity"]&&l["actualOrderId"].as_str().is_some()&&l["exchangeId"].as_str().is_some_and(|e|exchanges.contains(e))),"PORTFOLIO_PARTIAL_UNKNOWN_OR_CROSS_COMPONENT_PACKAGE")?;parents.push(package["packageId"].as_str().ok_or("PORTFOLIO_PACKAGE_ID")?.into());}
 let floor=c.compiled().portfolio_floor(&held)?;let age=p.max_book_age_ms.min(policy["bookAgeMs"].as_u64().ok_or("PORTFOLIO_POLICY")?);let(books,hashes)=package_admission::native_books(bank,c.scope(),p.now_ms,age)?;
 let mut expires=p.now_ms.checked_add(policy["lifetimeMs"].as_u64().ok_or("PORTFOLIO_POLICY")?).ok_or("PORTFOLIO_CLOCK")?.min(c.expires_at_ms());if buy{expires=expires.min(entry_until)}need(expires>p.now_ms.checked_add(policy["latencyMs"].as_u64().ok_or("PORTFOLIO_POLICY")?).ok_or("PORTFOLIO_CLOCK")?,"PORTFOLIO_LIFETIME")?;
 let mut maximum_payout=0i128;for state in c.compiled().states(){let mut payout=0;for(i,q)in &held{payout=add(payout,mul(if i.side==Side::Yes{state[i.contract].0}else{state[i.contract].1},*q)?)?;}maximum_payout=maximum_payout.max(payout);}let mut liquidation_cash=Some(0i128);for(i,q)in &held{let contract=&c.compiled().contracts()[i.contract];let next=books.get(&contract.exchange_id).and_then(|b|depth_cost(if i.side==Side::Yes{&b.yes_bids}else{&b.no_bids},*q,false).ok());liquidation_cash=match(liquidation_cash,next){(Some(sum),Some(n))=>Some(add(sum,n)?),_=>None};}Ok(Context{held,holdings:json!(holdings),parents,books,hashes,floor,maximum_payout,liquidation_cash,expires})
}
fn limit(levels:&[Level],q:u64,buy:bool)->Result<i128>{depth_cost(levels,q,buy)?;let mut left=q;for l in levels{left=left.saturating_sub(l.quantity);if left==0{return Ok(l.price)}}Err("PORTFOLIO_DEPTH".into())}
fn make_leg(c:&CertifiedComponent,x:&Context,i:Instrument,q:u64,buy:bool)->Result<(Leg,i128,u64)>{let contract=&c.compiled().contracts()[i.contract];if buy{need(!x.held.iter().any(|(held,_)|held.contract==i.contract&&held.side!=i.side),"PORTFOLIO_OPPOSITE_HELD_NETTING_UNSUPPORTED")?;}let b=x.books.get(&contract.exchange_id).ok_or("PORTFOLIO_CURRENT_BOOK_MISSING")?;let levels=match(i.side,buy){(Side::Yes,true)=>&b.yes_asks,(Side::No,true)=>&b.no_asks,(Side::Yes,false)=>&b.yes_bids,(Side::No,false)=>&b.no_bids};let price=limit(levels,q,buy)?;need((5000..=995000).contains(&price)&&price%5000==0,"PORTFOLIO_WIRE_TICK")?;Ok((Leg{market_id:contract.market_id.clone(),exchange_id:contract.exchange_id.clone(),contract_id:contract.contract_id.clone(),side:side(i.side).into(),action:if buy{"buy"}else{"sell"}.into(),quantity:q,limit_price:money(price),book_hash:x.hashes[&contract.exchange_id].clone()},mul(price,q)?,b.observed_ms))}
fn plan(bank:&Session,a:&Activation,c:&CertifiedComponent,p:&Policy,x:&Context,mode:Mode,legs:Vec<Leg>,cost:i128,cash:i128,after:i128,buffer:i128,improvement:i128,statewise:i128,class:&str)->Result<Plan>{
 let head=bank.durable_head();let portfolio=json!({"version":1,"mode":mode,"bankHead":head,"holdings":x.holdings,"componentExchanges":c.compiled().contracts().iter().map(|contract|contract.exchange_id.clone()).collect::<Vec<_>>(),"protectedPackageIds":x.parents,"floorBefore":money(x.floor),"floorAfter":money(after),"minimumCashProceeds":money(cash),"maximumPayoutBefore":money(x.maximum_payout),"minimumStatewiseDelta":money(add(statewise,buffer)?),"liquidationBenchmarkCash":x.liquidation_cash.map(money),"classification":class});
 let wire:Vec<_>=legs.iter().map(|l|json!({"marketId":l.market_id,"exchangeId":l.exchange_id,"side":l.side,"action":l.action,"quantity":l.quantity,"limitPrice":l.limit_price,"bookHash":l.book_hash})).collect();
 let proof=json!({"version":2,"mode":mode,"runId":a.run_id,"bankManifestHash":bank.manifest_hash(),"tournamentId":a.tournament_id,"atMs":p.now_ms,"expiresAtMs":x.expires,"maximumCommitted":a.maximum_committed,"maximumMarketCost":a.maximum_market_cost,"maximumQuantity":a.maximum_quantity,"component":c.source_binding(),"portfolio":portfolio,"wireLegs":wire,"grossFunding":money(cost),"worstOrphanCashLoss":money(cost),"minimumCashProceeds":money(cash),"floorBefore":money(x.floor),"floorAfter":money(after),"buffer":money(buffer),"minimumImprovementVsLiquidationBenchmark":money(improvement),"minimumStatewiseDelta":money(add(statewise,buffer)?),"classification":class,"guaranteedProfit":false,"fees":"0.000000","usesFutureCollateral":false,"realizedProfit":false});let digest=hash(&proof)?;let id=format!("pkg-{digest}");let stamp=daily_windows::iso(p.now_ms)?;
 let floor_delta=after.checked_sub(x.floor).ok_or("PORTFOLIO_RANGE")?;let guaranteed=add(cash,floor_delta)?;
 let reserve=json!({"type":"live_package_reserve","source":"moloch_live_dispatcher","receivedAt":stamp,"processedAt":stamp,"packageId":id,"proofHash":digest,"bankScope":{"runId":a.run_id,"bankManifestHash":bank.manifest_hash(),"tournamentId":a.tournament_id},"expiresAt":daily_windows::iso(x.expires)?,"portfolio":portfolio,"economics":{"maximumCost":money(cost),"minimumPayout":money(guaranteed),"minimumSurplus":money(guaranteed-cost),"feeTotal":"0.000000"},"legs":wire});Ok(Plan{mode,proof,reserve,legs,expires:x.expires,head,funding:cost,improvement,statewise:add(statewise,buffer)?,classification:class.into()})
}
/// Find positive marginal FLOOR gain at fully funded fixed BUY wire limits.
/// One leg is supported: completing an already held pair needs no fabricated
/// second leg. Official allOrNone accepts one leg; legacy BUY SDK is unchanged.
pub fn acquire(bank:&Session,a:&Activation,c:&CertifiedComponent,gross_cash:i128,p:&Policy,entry_until:u64)->Result<Option<Plan>>{
 let x=context(bank,a,c,p,entry_until,true)?;let liquidation=x.liquidation_cash.ok_or("PORTFOLIO_HELD_LIQUIDATION_DEPTH_REQUIRED")?;need(gross_cash>=0,"PORTFOLIO_CASH")?;let reserved=bank.engine().wallet.reserved()?;let available=bank.engine().wallet.cash.min(gross_cash).checked_sub(reserved).ok_or("PORTFOLIO_RANGE")?;let remaining=baal_transport_service::decimal_units(&a.maximum_committed)?.checked_sub(bank.engine().wallet.owned_cost()).and_then(|n|n.checked_sub(reserved)).ok_or("PORTFOLIO_RANGE")?;need(available>=0&&remaining>=0,"PORTFOLIO_CAPITAL")?;
 let mut quantities=BTreeSet::new();for q in &p.quantities{need(*q>0&&*q<=p.maximum_quantity&&quantities.insert(*q),"PORTFOLIO_QUANTITY")?;}
 let all:Vec<_>=(0..c.compiled().contracts().len()).flat_map(|contract|[Instrument{contract,side:Side::Yes},Instrument{contract,side:Side::No}]).collect();let mut best=None;let mut best_surplus=0;
 for mask in 1..(1usize<<all.len()){let instruments:Vec<_>=all.iter().enumerate().filter(|(i,_)|mask&(1<<i)!=0).map(|(_,v)|*v).collect();if instruments.len()>3{continue}let unique:BTreeSet<_>=instruments.iter().map(|i|i.contract).collect();if unique.len()!=instruments.len(){continue}
 for q in &quantities{if q.checked_mul(instruments.len() as u64).is_none_or(|n|n>a.maximum_quantity as u64){continue}let mut legs=vec![];let mut cost=0;let mut clocks=vec![];let mut after=x.held.clone();let mut invalid=false;
 for i in &instruments{let Ok((l,paid,at))=make_leg(c,&x,*i,*q,true)else{invalid=true;break};if add(bank.engine().wallet.market_cost(&l.exchange_id),paid)?>baal_transport_service::decimal_units(&a.maximum_market_cost)?{invalid=true;break}cost=add(cost,paid)?;clocks.push(at);legs.push(l);if let Some((_,held))=after.iter_mut().find(|(instrument,_)|instrument==i){*held=held.checked_add(*q).ok_or("PORTFOLIO_RANGE")?;}else{after.push((*i,*q));}}
 if invalid||cost>available||cost>remaining||clocks.iter().max().unwrap()-clocks.iter().min().unwrap()>p.max_book_skew_ms{continue}let floor=c.compiled().portfolio_floor(&after)?;let buffer=mul(p.buffer_per_share,*q)?;let surplus=floor.checked_sub(x.floor).and_then(|n|n.checked_sub(cost)).and_then(|n|n.checked_sub(buffer)).ok_or("PORTFOLIO_RANGE")?;
 let benchmark=floor.checked_sub(cost).and_then(|n|n.checked_sub(liquidation)).and_then(|n|n.checked_sub(buffer)).ok_or("PORTFOLIO_RANGE")?;let additions:Vec<_>=instruments.iter().map(|i|(*i,*q)).collect();let statewise=c.compiled().portfolio_floor(&additions)?.checked_sub(cost).and_then(|n|n.checked_sub(buffer)).ok_or("PORTFOLIO_RANGE")?;let class=if statewise>=p.minimum_surplus{"standalone_statewise_edge"}else{"risk_hedge_locked_vs_liquidation"};if surplus>=p.minimum_surplus&&benchmark>=p.minimum_surplus&&benchmark>best_surplus{best=Some(plan(bank,a,c,p,&x,Mode::MarginalAcquisition,legs,cost,0,floor,buffer,benchmark,statewise,class)?);best_surplus=benchmark;}
 }}Ok(best)
}
/// Sell the WHOLE certified component covering the selected completed package.
/// Any intersecting partial/unknown package or outside-component protection
/// denies. Full fixed SELL limit proceeds must exceed the floor surrendered.
pub fn whole_unwind(bank:&Session,a:&Activation,c:&CertifiedComponent,package_id:&str,p:&Policy,entry_until:u64)->Result<Option<Plan>>{
 let x=context(bank,a,c,p,entry_until,false)?;need(x.parents.iter().any(|id|id==package_id),"PORTFOLIO_COMPLETE_PACKAGE_REQUIRED")?;need(!x.held.is_empty(),"PORTFOLIO_NO_HOLDINGS")?;let total=x.held.iter().try_fold(0u64,|n,(_,q)|n.checked_add(*q).ok_or("PORTFOLIO_RANGE"))?;need(total<=a.maximum_quantity as u64,"PORTFOLIO_AGGREGATE_QUANTITY_CAP")?;
 let mut legs=vec![];let mut cash=0;let mut clocks=vec![];for(i,q)in &x.held{let(l,proceeds,at)=make_leg(c,&x,*i,*q,false)?;cash=add(cash,proceeds)?;clocks.push(at);legs.push(l);}need(clocks.iter().max().unwrap()-clocks.iter().min().unwrap()<=p.max_book_skew_ms,"PORTFOLIO_BOOK_SKEW")?;let buffer=mul(p.buffer_per_share,x.held.iter().map(|(_,q)|*q).max().unwrap())?;let improvement=cash.checked_sub(x.maximum_payout).and_then(|n|n.checked_sub(buffer)).ok_or("PORTFOLIO_RANGE")?;if improvement<p.minimum_surplus{return Ok(None)}Ok(Some(plan(bank,a,c,p,&x,Mode::WholeUnwind,legs,0,cash,0,buffer,improvement,improvement,"statewise_cash_unwind_edge")?))
}
